@namespace sv_be737753d9dd4039a7565976ec81120d.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_be737753d9dd4039a7565976ec81120d.Components.Pages.Settings
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p>Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@_editModel.AvatarUrl" alt="Avatar" class="avatar-image" />
                <p class="avatar-url">@_editModel.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_editModel.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_editModel.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_editModel.Bio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveChanges">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private ProfileEditModel _editModel = new();
    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        LoadFromSaved();
        _loading = false;
    }

    private void LoadFromSaved()
    {
        if (_savedProfile is null) return;
        _editModel = new ProfileEditModel
        {
            DisplayName = _savedProfile.DisplayName,
            Email = _savedProfile.Email,
            AvatarUrl = _savedProfile.AvatarUrl,
            Bio = _savedProfile.Bio
        };
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(
            _editModel.DisplayName,
            _editModel.Email,
            _editModel.AvatarUrl,
            _editModel.Bio);

        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _showSuccess = true;
        StateHasChanged();

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        LoadFromSaved();
    }

    private class ProfileEditModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

@namespace sv_be737753d9dd4039a7565976ec81120d.Components.Pages.Settings
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p>Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span>Email Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span>Push Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                @foreach (var channel in _allChannels)
                {
                    <label class="toggle-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SavePreferences">Save Preferences</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Preferences saved!</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _showSuccess;

    // Simulated available channels
    private static readonly string[] _allChannels = { "General", "Engineering", "Marketing", "Support", "Random" };

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());

        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _showSuccess = true;
        StateHasChanged();

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

